// Sign outbound calls to the app: X-Pressline-Signature: t=<unix>,v1=<hmac sha256 hex of "<t>.<rawBody>">
const crypto = require('crypto');
const S = $('Secrets').first().json;
let secret; try { secret = $env.N8N_WEBHOOK_SECRET; } catch (e) { /* $env disabled */ }
if (!secret) secret = S.secret;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET missing: set it in n8n env or in the Secrets node');
const appUrl = String(S.appUrl || 'https://pressline.up.railway.app').replace(/\/+$/, '');
const n8nUrl = String(S.n8nUrl || 'https://deathcorps187.app.n8n.cloud').replace(/\/+$/, '');
const items = $input.all();
const calls = [];
calls.push({ path: '/api/webhooks/n8n', body: { kind: 'wholesale_prospects', limit: 25 } });
return calls.filter(Boolean).map((c) => {
  const method = String(c.method || 'POST').toUpperCase();
  const raw = method === 'GET' ? '' : JSON.stringify(c.body ?? {});
  const t = Math.floor(Date.now() / 1000);
  const mac = crypto.createHmac('sha256', secret).update(`${t}.${raw}`).digest('hex');
  const url = c.url || (appUrl + c.path);
  return { json: { url, method, raw, signature: `t=${t},v1=${mac}`, meta: c.meta || {} } };
});

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const wrap = (title, body) => `<div style="font-family:Helvetica,Arial,sans-serif;max-width:560px;margin:0 auto;padding:24px;color:#111"><h2 style="margin:0 0 16px">${esc(title)}</h2>${body}<p style="margin-top:32px;color:#888;font-size:12px">Midnight Fusion &middot; orders@midnightfusion.co</p></div>`;
const S = $('Secrets').first().json;
const appUrl = String(S.appUrl || '').replace(/\/+$/, '');
const prospects = $input.first().json.prospects || [];
return prospects.filter((c) => c.email).map((c) => {
  const first = String(c.name || '').split(' ')[0] || 'there';
  const shop = c.company || 'your shop';
  const url = `${appUrl}/wholesale?c=${encodeURIComponent(c.customer_id || c.id)}`;
  const body = `<p>${esc(first)} — a shop kit for ${esc(shop)}: 24 pieces, two designs, your logo on the tag, no minimums after the first run.</p>` + (c.niche ? `<p>Built for ${esc(c.niche)}.</p>` : '') + `<p><a href="${url}">See the kit and pricing</a></p>`;
  return { json: { email: { to: c.email, subject: `Shop kit for ${shop}`, html: wrap(`Shop kit for ${shop}`, body), text: `Shop kit for ${shop}: ${url}` }, customer_id: c.customer_id || c.id } };
});

